import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import './MySales.css';

const MySales = () => {
  const [sales, setSales] = useState([]);
  const [totalEarnings, setTotalEarnings] = useState(0);
  const userId = sessionStorage.getItem("userId");

  useEffect(() => {
    if (userId) {
      fetch(`${API_BASE_URL}/api/sales/user/${userId}`)
        .then((res) => res.json())
        .then((data) => {
          setSales(data);
          const total = data.reduce((sum, item) => sum + parseFloat(item.price), 0);
          setTotalEarnings(total);
        })
        .catch((err) => console.error("Error loading sales:", err));
    }
  }, [userId]);

  const toggleShipped = async (listingId) => {
    await fetch(`${API_BASE_URL}/api/listings/${listingId}/shipped`, { method: "PUT" });
    setSales((prev) =>
      prev.map((item) =>
        item.id === listingId ? { ...item, shipped: true } : item
      )
    );
  };

  const handleEarlyPayout = () => {
    const confirmPayout = window.confirm("Payout now for a 3% early payout charge?");
    if (confirmPayout) {
      const fee = totalEarnings * 0.03;
      const finalPayout = totalEarnings - fee;
      alert(
        `✅ Payout Successful!\nTotal: $${totalEarnings.toFixed(2)}\nEarly Fee (3%): -$${fee.toFixed(2)}\nFinal Payout: $${finalPayout.toFixed(2)}`
      );
      setTotalEarnings(0);
    }
  };

  return (
    <div className="page-container">
      <Navbar />
      <div className="main-footer-wrapper">
        <main className="my-sales-container">
          <div className="earnings-card">
            <h2>Total Earnings</h2>
            <p className="amount">${totalEarnings.toFixed(2)}</p>
            <p className="subtext">Weekly payout every Friday</p>
            {totalEarnings > 0 && (
              <button className="btn payout-btn" onClick={handleEarlyPayout}>
                💸 Payout Now
              </button>
            )}
          </div>

          <h2 className="section-title">Items Sold</h2>
          <div className="sales-list">
            {sales.length === 0 ? (
              <p className="no-sales">You haven't sold any items yet.</p>
            ) : (
              sales.map((item) => (
                <div key={item.id} className="sales-card-sketch">
                  <div className="left-image-box">
                    <img src={item.image} alt={item.title} />
                  </div>
                  <div className="right-details-box">
                    <h3>{item.title}</h3>
                    <p><strong>Category:</strong> {item.category}</p>
                    <p><strong>Price:</strong> ${parseFloat(item.price).toFixed(2)}</p>
                    <p><strong>Ship To:</strong> {item.shipping_info?.address1}, {item.shipping_info?.city}, {item.shipping_info?.state} {item.shipping_info?.zip}</p>
                    <p><strong>Status:</strong> {item.shipped ? "✅ Shipped" : "❌ Not Shipped"}</p>
                    {!item.shipped && (
                      <button className="mark-btn" onClick={() => toggleShipped(item.id)}>
                        Mark as Shipped
                      </button>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        </main>
        <Footer />
      </div>
    </div>
  );
};

export default MySales;
